import{_ as n,o,c as h,a5 as e}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Tổng hợp kiến thức dựng video (10/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-auto-edit-agent/KIEN_THUC_DUNG.md","filePath":"feature/video-auto-edit-agent/KIEN_THUC_DUNG.md"}'),c={name:"feature/video-auto-edit-agent/KIEN_THUC_DUNG.md"};function d(i,t,a,r,g,l){return o(),h("div",null,[...t[0]||(t[0]=[e('<h1 id="tong-hop-kien-thuc-dung-video-10-11-2026" tabindex="-1">Tổng hợp kiến thức dựng video (10/11/2026) <a class="header-anchor" href="#tong-hop-kien-thuc-dung-video-10-11-2026" aria-label="Permalink to &quot;Tổng hợp kiến thức dựng video (10/11/2026)&quot;">​</a></h1><p>Gom mọi nguồn anh đã sưu tập cho việc dựng video, nói rõ agent dựng tự động trên web đã dùng được gì và còn thiếu gì.</p><h2 id="_1-cac-nguon" tabindex="-1">1. Các nguồn <a class="header-anchor" href="#_1-cac-nguon" aria-label="Permalink to &quot;1. Các nguồn&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguồn</th><th>Nằm ở đâu</th><th>Nội dung chính</th><th>Agent web dùng chưa</th></tr></thead><tbody><tr><td><strong>Bộ thể loại DemoVideo</strong></td><td><code>F:\\self\\DemoVideo\\docs\\the-loai-video\\</code> (README, 1-ke-chuyen … 5-microdrama, khung-cau-truc)</td><td>19 thể loại: mục đích, thời lượng, nhịp cắt, khung theo mốc giây, chuyển cảnh, màu, nhạc, tiếng động, prompt dựng, phần &quot;Kiểm khung&quot;</td><td><strong>Có.</strong> Đóng gói trong <code>brandhub-ai-service/app/resources/video-edit/docs/</code>. Agent nhận mục khớp thể loại (ẩm thực/đồ uống đã thêm từ khóa matcha, trà, cà phê, latte)</td></tr><tr><td><strong>Quy trình dựng chung DemoVideo</strong></td><td><code>docs/video-edit/SKILL.md</code> + <code>references/</code> (QUY_TRINH, DUNG_THEO_THE_LOAI, DO_HOA_VA_AM_THANH, CONG_CU…)</td><td>Bước 0 soát nguồn → mục đích → dựng thô → chuyển cảnh → chữ → màu → 4 lớp âm thanh → QC → bàn giao</td><td><strong>Có</strong>, chắt lọc vào <code>editing-playbook.md</code></td></tr><tr><td><strong>Sổ lỗi DemoVideo</strong></td><td><code>tools/edit/LOI_DA_GAP.md</code></td><td>13 quy tắc: thời gian tính bằng frame, đếm frame trước khi xuất, chữ không chồng nhau, không dùng sed cho regex…</td><td><strong>Có</strong>, phần liên quan nằm trong playbook mục 8 và <code>server-lessons.md</code></td></tr><tr><td><strong>Thư viện tiếng động</strong></td><td><code>DemoVideo/tools/edit/sfx/</code> (72 tiếng CC0/public domain, NGUON.md)</td><td>Ẩm thực, chuyển cảnh, nhấn chữ, va chạm, không khí…</td><td><strong>Có</strong> (đã đóng gói vào worker)</td></tr><tr><td><strong>Nhạc CC0 Video Space Lab</strong></td><td><code>video-editor-lab/resources/assets/music</code>, worker <code>resources/product-video/music</code></td><td>5 bài kèm mood và BPM</td><td><strong>Có</strong></td></tr><tr><td><strong>Font OFL</strong></td><td>thư viện font Video Space</td><td>24 font, worker có 6 (Be Vietnam Pro, Oswald, Montserrat, Playfair Display, Bangers, Quicksand)</td><td><strong>Có</strong></td></tr><tr><td><strong>HyperFrames 0.8.170 + GSAP</strong></td><td>DemoVideo <code>node_modules</code>, worker <code>tools/hyperframes</code></td><td>Chữ và đồ họa động bằng HTML/GSAP, render nền trong suốt</td><td><strong>Có, qua 5 mẫu viết sẵn</strong>: kinetic-slam, mask-reveal, highlight-sweep, cta-pill, editorial</td></tr><tr><td><strong>EditAtlas</strong> (MCP <code>https://edit.trysometh.ing/mcp</code>, REST <code>/api/v1</code>)</td><td>Dịch vụ công khai</td><td>Kỹ thuật quay/dựng (match cut, match on motion, speed ramp, foley, b-roll đồ uống, macro), mẫu cấu trúc (Pour Ritual cho đồ uống, Meal Map, Recipe in Verbs), style (Beat Punch Cut…), SFX</td><td><strong>Một phần</strong>: trợ lý chat đã lấy template + style theo chủ đề drink/food. Agent server dùng kiến thức đã chắt vào playbook, chưa gọi EditAtlas lúc chạy</td></tr><tr><td><strong>Skill cài trong Claude Code</strong></td><td><code>~/.claude/skills</code>, plugin</td><td><code>fk-sound-design</code>, <code>fk-cinematic-transitions</code>, <code>fk-camera-guide</code>, <code>fk-action-choreography</code>, <code>taste</code>, <code>video-editing</code>, <code>opus-video-prompts</code> (703 prompt motion), bộ <code>hyperframes:*</code>, <code>seecut-vn</code>, <code>remotion-video-creation</code>, <code>motion-*</code></td><td>Gián tiếp: các nguyên tắc chuyển cảnh và âm thanh đã có trong tài liệu DemoVideo nên đã vào playbook. Prompt <code>opus-video-prompts</code> chưa dùng</td></tr><tr><td><strong>Bản dựng chuẩn của Claude DemoVideo</strong></td><td><code>video-editor-lab/test-assets/matcha-studio-20261031/ban-dung-claude/</code> (HANDOFF.md, dung.py)</td><td>3 shot dài nối khớp mạch; tránh frame lỗi 175; chữ kiểu tạp chí; foley rót khớp frame; nhạc né foley; chỉnh màu nhẹ; −14,3 LUFS</td><td><strong>Có</strong>, dùng làm thước đo chất lượng trong playbook</td></tr></tbody></table><p><strong>Về lệnh <code>claude mcp add --transport http --scope user EditAtlas https://edit.trysometh.ing/mcp</code>:</strong> lệnh này chỉ thêm EditAtlas cho <strong>Claude Code trên máy anh</strong>, không cấp cho backend. Worker và trợ lý chat gọi bản REST của cùng dịch vụ. Tôi chưa chạy lệnh vì nó sửa cấu hình chung của anh.</p><h2 id="_2-nguyen-tac-cot-loi-rut-gon-tu-tat-ca-nguon" tabindex="-1">2. Nguyên tắc cốt lõi (rút gọn từ tất cả nguồn) <a class="header-anchor" href="#_2-nguyen-tac-cot-loi-rut-gon-tu-tat-ca-nguon" aria-label="Permalink to &quot;2. Nguyên tắc cốt lõi (rút gọn từ tất cả nguồn)&quot;">​</a></h2><ol><li><strong>Chọn thể loại theo điều người xem phải cảm thấy hoặc làm</strong>, không theo nội dung footage.</li><li><strong>Soát nguồn trước khi dựng:</strong> frame giật, khung đen, đứng hình, chữ dính sẵn trong hình, tay méo, giật ở frame đầu clip AI.</li><li><strong>Chỉ cắt khi cắt có ích.</strong> Một hành động liền mạch (rót, lộ diện, nhấc ly) là nhân vật chính, cần giữ trọn. Không cắt giữa hai thời điểm của cùng một góc máy. Nối clip bằng match cut hoặc cut on motion.</li><li><strong>Chuyển cảnh mang nghĩa:</strong> cắt (giữ nhịp), hòa hình (thời gian trôi), tối dần (kết chương), trắng lóa (ký ức/va chạm), trượt (bước tiếp theo). Không chồng hiệu ứng lên mọi nhát.</li><li><strong>Chữ:</strong> ít chữ, đặt vào vùng trống của khung hình đúng lúc đó. Nằm trong vùng an toàn 9:16 (khoảng 12–75% chiều cao, tránh mép phải). Các lớp chữ không chồng lên nhau. Kiểu chữ hợp thể loại: editorial cho sản phẩm cao cấp, chữ &quot;slam&quot; cho affiliate/hype.</li><li><strong>Âm thanh 4 lớp:</strong> thoại, foley, không khí, nhạc. Foley khớp đúng frame hành động. Nhạc né thoại (ít nhất 10 LU) và né foley. Master −14 LUFS, true peak ≤ −1 dBTP.</li><li><strong>Một grade màu chung</strong> cho mọi clip, vì clip AI lệch màu nhau. Không làm sai màu sản phẩm.</li><li><strong>Xem lại như người xem</strong> ở mọi chữ, mọi điểm nối và đoạn kết. QC đạt chưa có nghĩa là đẹp.</li></ol><h2 id="_3-khung-cho-quang-cao-đo-an-đo-uong-muc-13–14-demovideo-editatlas-pour-ritual" tabindex="-1">3. Khung cho quảng cáo đồ ăn/đồ uống (mục 13–14 DemoVideo + EditAtlas Pour Ritual) <a class="header-anchor" href="#_3-khung-cho-quang-cao-đo-an-đo-uong-muc-13–14-demovideo-editatlas-pour-ritual" aria-label="Permalink to &quot;3. Khung cho quảng cáo đồ ăn/đồ uống (mục 13–14 DemoVideo + EditAtlas Pour Ritual)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mốc</th><th>Phần</th><th>Hình</th><th>Âm thanh</th><th>Chuyển</th></tr></thead><tbody><tr><td>0–3 s</td><td>Hook: hành động đẹp nhất hoặc thành phẩm, tên món</td><td>Cận, hành động đang diễn ra ngay frame đầu</td><td>Foley của hành động, nhạc vào nhẹ</td><td>—</td></tr><tr><td>3–15 s</td><td>Các bước (rót, khuấy, vân lan)</td><td>Mỗi bước một shot trọn, chậm nhẹ ở khoảnh khắc ngon nhất</td><td>Foley khớp frame, nhạc né</td><td>Cắt khớp mạch / match cut</td></tr><tr><td>15–20 s</td><td>Thành phẩm + lời mời</td><td>Tay nhấc ly, giữ hình</td><td>Nhạc dâng, fade out</td><td>Cắt hoặc hòa hình</td></tr></tbody></table><p>Kiểm khung: 3 giây đầu có hành động hoặc thành phẩm không? Âm thật có rõ hơn nhạc không? Có đúng một thông điệp và một lời mời không?</p><h2 id="_4-đa-đua-vao-agent-web-10-11-2026" tabindex="-1">4. Đã đưa vào agent web (10/11/2026) <a class="header-anchor" href="#_4-đa-đua-vao-agent-web-10-11-2026" aria-label="Permalink to &quot;4. Đã đưa vào agent web (10/11/2026)&quot;">​</a></h2><ul><li><code>editing-playbook.md</code> thay các luật ép cắt cũ (6–12 shot, bắt buộc khớp beat, punch). Luật cũ chính là nguyên nhân jump cut ở lần chạy 3.</li><li>Soát nguồn: <code>detect_scenes</code> trả số frame, cắt cảnh, frame giật, khung đen, đứng hình. Đã kiểm trên matcha: phát hiện đúng clip 02 frame 175 và clip 01 frame 181.</li><li><code>view_frames</code> ghi số frame lên từng ảnh.</li><li>Cổng kiểm tra khi nộp plan: <ul><li>shot không được đi qua lỗi nguồn hay cắt cảnh;</li><li>chặn jump cut (2 shot cùng góc máy không liền mạch);</li><li>chữ không chồng nhau;</li><li>phải xem bản nháp trước khi nộp.</li></ul></li><li>Âm thanh: <code>duck_music</code>, <code>lowpass_hz</code>, <code>fade_frames</code> cho foley; nhạc né foley.</li><li>Chữ: mẫu HyperFrames <code>editorial</code> (dòng phụ + tiêu đề serif, không nền, bóng mờ tự đổi theo màu chữ, căn trái/giữa); <code>render_preview</code> có tùy chọn xem cận vùng chữ.</li><li>Màu: <code>grade</code> (contrast, saturation, độ ấm) áp cho mọi clip.</li></ul><h2 id="_5-con-thieu" tabindex="-1">5. Còn thiếu <a class="header-anchor" href="#_5-con-thieu" aria-label="Permalink to &quot;5. Còn thiếu&quot;">​</a></h2><ul><li>Video mẫu của brand (<code>BRAND_REFERENCE</code> trong repository) chưa được đưa cho agent xem.</li><li>EditAtlas chưa được agent server gọi lúc chạy (hiện chỉ dùng kiến thức đã chắt lọc).</li><li>Chuyển cảnh mới chỉ có cut/dissolve/dip/slide. Bảng DemoVideo còn iris, whip, zoom, wipe, gray, light leak.</li><li>Chưa crop/pan có điểm lấy nét để tạo cận cảnh từ cùng một clip.</li><li>Thư viện nhạc mới có 5 bài.</li></ul>',14)])])}const m=n(c,[["render",d]]);export{s as __pageData,m as default};
